    private TextView title,artist,status,time;private ImageView art;private ImageButton play;private Button shuffle,repeat;
    private SeekBar seek;private ListView queue;private BaseAdapter rows;private boolean dragging,started,handledIntent;
    private final Handler handler=new Handler(Looper.getMainLooper());
