        LinearLayout queueHead=ui.row();queueHead.setPadding(ui.dp(16),ui.dp(8),ui.dp(16),0);queueHead.addView(ui.heading(tr(R.string.ui_queue_d325fc),16),new LinearLayout.LayoutParams(0,-2,1));queueHead.addView(ui.icon("more",tr(R.string.ui_queue_and_sleep_timer_options_90987c),this::options));root.addView(queueHead);
