    @Override protected void onStart(){super.onStart();started=true;connection=new MediaController.Builder(this,new SessionToken(this,new ComponentName(this,AudioService.class))).buildAsync();final ListenableFuture<MediaController> pending=connection;connection.addListener(()->{try{if(!started||connection!=pending)return;controller=pending.get();controller.addListener(listener);refresh();if(!handledIntent){handledIntent=true;String local=getIntent().getStringExtra("local_playlist"),raw=getIntent().getStringExtra("video");if(local!=null)load(local);else if(raw!=null)startQueue(Collections.singletonList(Video.fromJson(new org.json.JSONObject(raw))));}}catch(Exception e){error(tr(R.string.ui_couldn_t_connect_to_the_audio_player_please_reop_8c89ee));}},this::runOnUiThread);handler.post(tick);}
