    private void refresh(){if(controller==null)return;MediaMetadata m=controller.getMediaMetadata();if(controller.getMediaItemCount()>0){title.setText(m.title==null?tr(R.string.ui_audio_acdac2):m.title);artist.setText(m.artist==null?"":m.artist);String url=m.artworkUri==null?"":m.artworkUri.toString();if(!url.equals(art.getTag()))app.thumbnails.load(url,art);}play.setImageDrawable(new AppIcons(controller.isPlaying()?"pause":"play",ui.accent));shuffle.setText(controller.getShuffleModeEnabled()?tr(R.string.ui_shuffle_on_785728):tr(R.string.ui_shuffle_off_e59f97));repeat.setText(controller.getRepeatMode()==Player.REPEAT_MODE_ONE?tr(R.string.ui_repeat_track_07d5e1):controller.getRepeatMode()==Player.REPEAT_MODE_ALL?tr(R.string.ui_repeat_queue_2a9843):tr(R.string.ui_repeat_off_c4d7b8));PlaybackException error=controller.getPlayerError();status.setText(error!=null?tr(R.string.ui_couldn_t_play_this_track_1_s_tap_play_to_retry_o_a66f14, error.getErrorCodeName()):controller.getPlaybackState()==Player.STATE_BUFFERING?tr(R.string.ui_loading_audio_011ae4):controller.getMediaItemCount()==0?"":controller.isPlaying()?tr(R.string.ui_audio_only_continues_with_the_screen_off_baf013):tr(R.string.ui_paused_c7dfb6));rows.notifyDataSetChanged();refreshPosition();}
    private void refreshPosition(){if(controller==null||dragging)return;if(AudioService.queueLoading)status.setText(tr(R.string.ui_loading_playlist_0f0b75));else if(!AudioService.queueError.isEmpty())status.setText(tx(AudioService.queueError));long duration=controller.getDuration(),position=controller.getCurrentPosition();seek.setEnabled(duration>0);seek.setMax((int)Math.min(Integer.MAX_VALUE,Math.max(0,duration)));seek.setProgress((int)Math.min(Integer.MAX_VALUE,position));time.setText(clock(position)+" / "+clock(Math.max(0,duration))+(AudioService.sleepUntil>0?" · "+tx("Sleep timer")+" "+Math.max(1,(AudioService.sleepUntil-SystemClock.elapsedRealtime()+59999)/60000)+"m":""));}
    private static String clock(long ms){long s=ms/1000;return String.format(Locale.ROOT,"%d:%02d",s/60,s%60);}
    private void choosePlaylist(){if(controller==null){toast(tr(R.string.ui_audio_player_is_connecting_c37579));return;}LibraryStore library=app.library;work(app.disk,library::playlists,lists->{List<String> names=new ArrayList<>();names.add(tx("Saved videos"));for(LibraryStore.LocalPlaylist p:lists)names.add(p.name+" · "+p.size+" tracks");new AlertDialog.Builder(this).setTitle(tr(R.string.ui_play_audio_from_b6a4f8)).setItems(names.toArray(new String[0]),(d,i)->load(i==0?"":lists.get(i-1).id)).setNegativeButton(tr(R.string.ui_cancel_77dfd2),null).show();},this::error);}
    private void load(String id){if(controller==null)return;startService(new Intent(this,AudioService.class).setAction("playlist").putExtra("id",id).putExtra("profile",app.prefs.text("profile","default")));status.setText(tr(R.string.ui_loading_playlist_0f0b75));}
    private void startQueue(List<Video> videos){if(controller==null||videos.isEmpty())return;startService(new Intent(this,AudioService.class).setAction("video").putExtra("video",videos.get(0).json().toString()).putExtra("profile",app.prefs.text("profile","default")));status.setText(tr(R.string.ui_loading_audio_011ae4));}
    private void chooseAudioTrack(){if(controller==null||controller.getCurrentMediaItem()==null)return;String id=controller.getCurrentMediaItem().mediaId;work(app.media,()->app.youtube.media(id),media->{if(controller==null||controller.getCurrentMediaItem()==null||!id.equals(controller.getCurrentMediaItem().mediaId))return;if(media.audioTracks.isEmpty()){toast(tx("No audio tracks available"));return;}int selected=0;for(int i=0;i<media.audioTracks.size();i++)if(AudioTrackPolicy.key(media.audioTracks.get(i)).equals(media.audioTrackId))selected=i;new AlertDialog.Builder(this).setTitle(tx("Audio track")).setSingleChoiceItems(AudioTrackLabels.labels(this,media.audioTracks),selected,(dialog,index)->{dialog.dismiss();String key=AudioTrackPolicy.key(media.audioTracks.get(index));work(app.media,()->app.youtube.selectAudioTrack(id,key),updated->{if(controller==null||controller.getCurrentMediaItem()==null||!id.equals(controller.getCurrentMediaItem().mediaId))return;long at=controller.getCurrentPosition();boolean playing=controller.getPlayWhenReady();controller.stop();controller.seekTo(at);controller.prepare();if(playing)controller.play();toast(tx("Audio track changed"));},this::error);}).setNegativeButton(tx("Cancel"),null).show();},this::error);}
    private void options(){new AlertDialog.Builder(this).setTitle(tr(R.string.ui_audio_options_605c8b)).setItems(new String[]{tr(R.string.ui_sleep_timer_e90613),tr(R.string.ui_clear_queue_and_stop_ab7714),tr(R.string.ui_audio_network_settings_963963),tx("Audio track")},(d,i)->{if(i==0)new AlertDialog.Builder(this).setTitle(tr(R.string.ui_stop_audio_after_d3a7b5)).setItems(new String[]{tr(R.string.ui_off_e3de5a),tr(R.string.ui_15_minutes_899761),tr(R.string.ui_30_minutes_31bbe8),tr(R.string.ui_60_minutes_ee8eb1),tr(R.string.ui_120_minutes_af74ba)},(dialog,n)->{int minutes=new int[]{0,15,30,60,120}[n];if(minutes>0&&(controller==null||controller.getMediaItemCount()==0)){toast(tr(R.string.ui_start_audio_before_setting_a_sleep_timer_6be670));return;}startService(new Intent(this,AudioService.class).setAction("sleep").putExtra("minutes",minutes));toast(minutes==0?tr(R.string.ui_sleep_timer_off_1dbcb9):tr(R.string.ui_sleep_timer_set_b28b6d));}).show();else if(i==1&&controller!=null){startService(new Intent(this,AudioService.class).setAction("clear"));art.setTag(null);art.setImageDrawable(null);title.setText(tr(R.string.ui_your_music_your_queue_cd6677));artist.setText(tr(R.string.ui_choose_a_playlist_to_start_listening_b0cc63));}else if(i==3)chooseAudioTrack();else if(i==2)startActivity(new Intent(this,MainActivity.class).putExtra("open_screen","Settings"));}).show();}
